export function completeJob(db: DatabaseSync, id: string, output: string): void {
  db.prepare(
    "UPDATE jobs SET status = 'completed', completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE id = ?",
  ).run(output, new Date().toISOString(), id);
}

export function failJob(db: DatabaseSync, id: string, error: string): void {
  db.prepare(
    "UPDATE jobs SET status = 'failed', result_output = NULL, error = ?, updated_at = ? WHERE id = ?",
  ).run(error, new Date().toISOString(), id);
}

export function requeueForRetry(db: DatabaseSync, id: string, runAt: number): void {
  db.prepare("UPDATE jobs SET status = 'queued', next_run_at = ?, updated_at = ? WHERE id = ?").run(
    runAt,
    new Date().toISOString(),
    id,
  );
}

export function writeHeartbeat(db: DatabaseSync, now: number = Date.now()): void {
  db.prepare(
    'INSERT INTO heartbeat (id, ts) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET ts = excluded.ts',
  ).run(now);
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.prepare('DELETE FROM heartbeat').run();
}

/** True when the worker wrote a heartbeat within the last `maxAgeMs` milliseconds. */
export function isWorkerUp(db: DatabaseSync, maxAgeMs = 3000, now: number = Date.now()): boolean {
  const row = one<{ ts: number }>(db, 'SELECT ts FROM heartbeat WHERE id = 1');
  return row !== undefined && now - row.ts <= maxAgeMs;
}

import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  clearHeartbeat,
  claimNextJob,
  completeJob,
  failJob,
  recordProgress,
  recoverInterruptedJobs,
  requeueForRetry,
  writeHeartbeat,
  type ClaimedJob,
} from './jobs.ts';
import type { DatabaseSync } from 'node:sqlite';

const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;
const IDLE_POLL_MS = 200;
const HEARTBEAT_MS = 1000;

const db: DatabaseSync = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

const recovered = recoverInterruptedJobs(db);
writeHeartbeat(db);
const heartbeat = setInterval(() => {
  try {
    writeHeartbeat(db);
  } catch (e) {
    console.error('heartbeat failed:', e);
  }
}, HEARTBEAT_MS);
console.log(`worker started (re-queued ${recovered} interrupted attempt(s))`);

/** Processes one attempt. Returns early, leaving the job `running`, if the worker is stopping. */
async function runAttempt(job: ClaimedJob): Promise<void> {
  if (job.attempt <= job.failAttempts) {
    // The simulated dependency fails at the first step, before any progress is recorded.
    await sleep(STEP_MS);
    if (stopping) return;
    if (job.attempt >= MAX_ATTEMPTS) failJob(db, job.id, 'transient failure');
    else requeueForRetry(db, job.id, Date.now() + RETRY_DELAY_MS);
    return;
  }

  for (let done = 1; done <= job.steps; done++) {
    await sleep(STEP_MS);
    if (stopping) return;
    recordProgress(db, job.id, done);
  }
  completeJob(db, job.id, job.input.toUpperCase());
}

while (!stopping) {
  try {
    const job = claimNextJob(db);
    if (job) await runAttempt(job);
    else await sleep(IDLE_POLL_MS);
  } catch (e) {
    console.error('worker loop error:', e);
    await sleep(IDLE_POLL_MS);
  }
}

clearInterval(heartbeat);
// Roll back any attempt cut short by the shutdown so the next start re-runs it.
recoverInterruptedJobs(db);
clearHeartbeat(db);
db.close();
console.log('worker stopped');

